settings.custom_css:
selector {
	animation: flutuando03 15s ease;
	animation-iteration-count: infinite;
}
 
@keyframes flutuando03 {
	0% {
    	transform: translateY(0px) rotate(5deg);
	} 50% {
    	transform: translateY(-30px) rotate(-5deg);
	} 100% {
    	transform: translateY(0px) rotate(5deg);
	}
}
